String jdbcUrl = "jdbc:h2:mem:lesson01;DB_CLOSE_DELAY=-1";

try (Connection connection = DriverManager.getConnection(jdbcUrl, "sa", "")) {
    Statement statement = connection.createStatement();
    statement.execute("CREATE TABLE products (id INT PRIMARY KEY, name VARCHAR(100))");
    statement.execute("INSERT INTO products VALUES (1, 'Laptop')");

    ResultSet resultSet = statement.executeQuery("SELECT name FROM products WHERE id = 1");
    resultSet.next();
    assertThat(resultSet.getString("name")).isEqualTo("Laptop");
}

